  "controlled": "'use client';\n\nimport React, { useState } from 'react';\nimport { CommentOutlined, CustomerServiceOutlined } from '@ant-design/icons';\nimport { FloatButton, Switch } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [open, setOpen] = useState<boolean>(true);\n  return (\n    <>\n      <Switch onChange={setOpen} checked={open} style={{ margin: 16 }} />\n      <FloatButton.Group\n        open={open}\n        trigger=\"click\"\n        style={{ insetInlineEnd: 24 }}\n        icon={<CustomerServiceOutlined />}\n      >\n        <FloatButton />\n        <FloatButton />\n        <FloatButton icon={<CommentOutlined />} />\n      </FloatButton.Group>\n      <FloatButton.Group\n        open={open}\n        shape=\"square\"\n        trigger=\"click\"\n        style={{ insetInlineEnd: 88 }}\n        icon={<CustomerServiceOutlined />}\n      >\n        <FloatButton />\n        <FloatButton />\n        <FloatButton icon={<CommentOutlined />} />\n      </FloatButton.Group>\n    </>\n  );\n};\n\nexport default App;\n\n",
  "draggable": "'use client';\n\nimport React from 'react';\nimport type { DragEndEvent } from '@dnd-kit/core';\nimport { DndContext, PointerSensor, useDraggable, useSensor, useSensors } from '@dnd-kit/core';\nimport { CSS } from '@dnd-kit/utilities';\nimport { FloatButton } from '@ceebee/ui/client';\n\ninterface Position {\n  x: number;\n  y: number;\n}\n\ninterface DraggableButtonProps {\n  position: Position;\n}\n\nconst DraggableButton: React.FC<DraggableButtonProps> = (props) => {\n  const { position } = props;\n\n  const { attributes, isDragging, listeners, setNodeRef, transform } = useDraggable({\n    id: 'draggable-float-button',\n  });\n\n  const mergedTransform = CSS.Translate.toString({\n    x: position.x + (transform?.x ?? 0),\n    y: position.y + (transform?.y ?? 0),\n    scaleX: transform?.scaleX ?? 1,\n    scaleY: transform?.scaleY ?? 1,\n  });\n\n  return (\n    <FloatButton\n      ref={setNodeRef}\n      {...listeners}\n      {...attributes}\n      style={{\n        transform: mergedTransform,\n        cursor: isDragging ? 'grabbing' : 'grab',\n        transition: isDragging ? 'none' : undefined,\n        touchAction: 'none',\n      }}\n    />\n  );\n};\n\nconst Demo: React.FC = () => {\n  const [position, setPosition] = React.useState<Position>({ x: 0, y: 0 });\n\n  const sensor = useSensor(PointerSensor, {\n    activationConstraint: {\n      distance: 10,\n    },\n  });\n\n  const sensors = useSensors(sensor);\n\n  const onDragEnd = (event: DragEndEvent) => {\n    const { delta } = event;\n    setPosition(({ x, y }) => ({ x: x + delta.x, y: y + delta.y }));\n  };\n\n  return (\n    <DndContext sensors={sensors} onDragEnd={onDragEnd} id=\"float-button-draggable\">\n      <DraggableButton position={position} />\n    </DndContext>\n  );\n};\n\nexport default Demo;\n\n",
