  "placement": "'use client';\n\nimport React from 'react';\nimport {\n  CommentOutlined,\n  DownOutlined,\n  LeftOutlined,\n  RightOutlined,\n  UpOutlined,\n} from '@ant-design/icons';\nimport { Flex, FloatButton } from '@ceebee/ui/client';\n\nconst BOX_SIZE = 100;\nconst BUTTON_SIZE = 40;\n\nconst wrapperStyle: React.CSSProperties = {\n  width: '100%',\n  height: '100vh',\n  overflow: 'hidden',\n  position: 'relative',\n};\n\nconst boxStyle: React.CSSProperties = {\n  width: BOX_SIZE,\n  height: BOX_SIZE,\n  position: 'relative',\n};\n\nconst insetInlineEnd: React.CSSProperties['insetInlineEnd'][] = [\n  (BOX_SIZE - BUTTON_SIZE) / 2,\n  -(BUTTON_SIZE / 2),\n  (BOX_SIZE - BUTTON_SIZE) / 2,\n  BOX_SIZE - BUTTON_SIZE / 2,\n];\n\nconst bottom: React.CSSProperties['bottom'][] = [\n  BOX_SIZE - BUTTON_SIZE / 2,\n  (BOX_SIZE - BUTTON_SIZE) / 2,\n  -BUTTON_SIZE / 2,\n  (BOX_SIZE - BUTTON_SIZE) / 2,\n];\n\nconst icons = [\n  <UpOutlined key=\"up\" />,\n  <RightOutlined key=\"right\" />,\n  <DownOutlined key=\"down\" />,\n  <LeftOutlined key=\"left\" />,\n];\n\nconst App: React.FC = () => (\n  <Flex justify=\"space-evenly\" align=\"center\" style={wrapperStyle}>\n    <div style={boxStyle}>\n      {(['top', 'right', 'bottom', 'left'] as const).map((placement, i) => {\n        const style: React.CSSProperties = {\n          position: 'absolute',\n          insetInlineEnd: insetInlineEnd[i],\n          bottom: bottom[i],\n        };\n        return (\n          <FloatButton.Group\n            key={placement}\n            trigger=\"click\"\n            placement={placement}\n            style={style}\n            icon={icons[i]}\n          >\n            <FloatButton />\n            <FloatButton icon={<CommentOutlined />} />\n          </FloatButton.Group>\n        );\n      })}\n    </div>\n  </Flex>\n);\n\nexport default App;\n\n",
